import { auth0 } from './lib/auth0';

// Next.js 16 replaces middleware.ts with proxy.ts as the network interception
// boundary (SPEC.md §3.2, §17 item 7).
export async function proxy(request: Request) {
  return await auth0.middleware(request);
}

export const config = {
  matcher: ['/((?!_next/static|_next/image|favicon.ico|sitemap.xml|robots.txt).*)'],
};
import 'server-only';
import { Auth0Client } from '@auth0/nextjs-auth0/server';

// Loads AUTH0_DOMAIN / AUTH0_CLIENT_ID / AUTH0_CLIENT_SECRET / AUTH0_SECRET /
// APP_BASE_URL from the environment; see SPEC.md §8 and §17 item 7.
export const auth0 = new Auth0Client();
import 'server-only';
import postgres from 'postgres';
import { getEnv } from './env';

const env = getEnv();

/**
 * One small pool per long-lived Node process (SPEC.md §3.1) — Tiger's free
 * tier excludes connection pooling, and postgres.js connects lazily on first
 * query, so constructing this at module load does not open a connection.
 *
 * `MISE_TEST_DB=1` (set by `npm run test:db`) points at DATABASE_URL_TEST,
 * a Tiger fork — never production.
 */
const url =
  process.env.MISE_TEST_DB === '1' ? (env.DATABASE_URL_TEST ?? '') : (env.DATABASE_URL ?? '');

const sql = postgres(url, {
  max: env.DB_POOL_MAX ?? 5,
  ssl: 'require',
});

export default sql;
import 'server-only';
import { z } from 'zod';

const schema = z.object({
  AUTH0_DOMAIN: z.string().min(1),
  AUTH0_CLIENT_ID: z.string().min(1),
  AUTH0_CLIENT_SECRET: z.string().min(1),
  AUTH0_SECRET: z.string().min(1),
  APP_BASE_URL: z.string().url().optional(),

  DATABASE_URL: z.string().min(1),
  DB_POOL_MAX: z.coerce.number().int().positive().default(5),
  DATABASE_URL_TEST: z.string().optional(),

  GEMINI_API_KEY: z.string().min(1),
  GEMINI_MODEL: z.string().default('gemini-3.8-flash'),
  GEMINI_SEARCH_MODEL: z.string().default('gemini-3.8-flash'),

  DATAANDAPIS_KEY: z.string().min(1),
  OFF_BASE_URL: z.string().url().default('https://world.openfoodfacts.org'),
  OFF_USER_AGENT: z.string().min(1),
  RECIPE_FETCH_USER_AGENT: z.string().min(1),

  ELEVENLABS_API_KEY: z.string().optional(),
  ELEVENLABS_VOICE_ID: z.string().default('JBFqnCBsd6RMkjVDRZzb'),
  ELEVENLABS_MODEL_ID: z.string().default('eleven_flash_v2_5'),

  DEFAULT_TZ: z.string().default('America/Vancouver'),
});

type Env = z.infer<typeof schema>;

let cached: Env | null = null;

/**
 * Validates server env vars with Zod and fails fast. Skipped during `vitest`
 * (NODE_ENV=test) so pure unit tests don't need every production secret —
 * anything that actually calls an external API should mock its own env reads.
 */
export function getEnv(): Env {
  if (cached) return cached;
  if (process.env.NODE_ENV === 'test') {
    cached = schema.partial().parse(process.env) as Env;
    return cached;
  }
  const parsed = schema.safeParse(process.env);
  if (!parsed.success) {
    console.error('[env] invalid/missing environment variables:', parsed.error.flatten().fieldErrors);
    throw new Error('Invalid environment configuration — see logs above.');
  }
  cached = parsed.data;
  return cached;
}
export class UnauthorizedError extends Error {}
export class NotFoundError extends Error {}
export class ConflictError extends Error {}
export class RateLimitedError extends Error {
  constructor(
    message: string,
    public retryAfterMs: number,
  ) {
    super(message);
  }
}
export class UnprocessableError extends Error {
  constructor(
    message: string,
    public details?: unknown,
  ) {
    super(message);
  }
}
import { NextResponse } from 'next/server';
import { ZodError } from 'zod';
import type { ApiError, ApiErrorCode } from '@/contracts/api';
import {
  ConflictError,
  NotFoundError,
  RateLimitedError,
  UnauthorizedError,
  UnprocessableError,
} from './errors';

const STATUS_BY_CODE: Record<ApiErrorCode, number> = {
  UNAUTHORIZED: 401,
  BAD_REQUEST: 400,
  NOT_FOUND: 404,
  CONFLICT: 409,
  RATE_LIMITED: 429,
  UPSTREAM_UNAVAILABLE: 502,
  UNPROCESSABLE: 422,
  PAYLOAD_TOO_LARGE: 413,
  INTERNAL: 500,
};

export function jsonOk<T>(data: T, init?: ResponseInit) {
  return NextResponse.json(data, init);
}

export function jsonError(code: ApiErrorCode, message: string, details?: unknown): NextResponse<ApiError> {
  return NextResponse.json({ error: { code, message, details } }, { status: STATUS_BY_CODE[code] });
}

export function jsonErrorFromZod(error: ZodError): NextResponse<ApiError> {
  return jsonError('BAD_REQUEST', 'Validation failed', error.flatten());
}

/** Converts a thrown error into the right typed ApiError response. Catch-all for route handlers. */
export function handleRouteError(err: unknown): NextResponse<ApiError> {
  if (err instanceof UnauthorizedError) return jsonError('UNAUTHORIZED', err.message || 'Not signed in');
  if (err instanceof NotFoundError) return jsonError('NOT_FOUND', err.message || 'Not found');
  if (err instanceof ConflictError) return jsonError('CONFLICT', err.message || 'Conflict');
  if (err instanceof UnprocessableError) return jsonError('UNPROCESSABLE', err.message, err.details);
  if (err instanceof RateLimitedError) {
    const res = jsonError('RATE_LIMITED', err.message || 'Too many requests');
    res.headers.set('Retry-After', String(Math.ceil(err.retryAfterMs / 1000)));
    return res;
  }
  if (err instanceof ZodError) return jsonErrorFromZod(err);
  console.error(err);
  return jsonError('INTERNAL', 'Something went wrong');
}

/**
 * Streams one JSON object per line as `application/x-ndjson`. `producer`
 * receives a `write` callback and should await every upstream step before
 * writing the matching event, so clients see progress instead of one
 * buffered burst at the end.
 */
export function ndjsonResponse<T>(producer: (write: (event: T) => void) => Promise<void>): Response {
  const encoder = new TextEncoder();
  const stream = new ReadableStream<Uint8Array>({
    async start(controller) {
      const write = (event: T) => controller.enqueue(encoder.encode(`${JSON.stringify(event)}\n`));
      try {
        await producer(write);
      } catch (err) {
        write({
          type: 'error',
          error: { code: 'INTERNAL', message: err instanceof Error ? err.message : 'Unknown error' },
        } as T);
      } finally {
        controller.close();
      }
    },
  });
  return new Response(stream, {
    headers: {
      'Content-Type': 'application/x-ndjson; charset=utf-8',
      'Cache-Control': 'no-cache',
      'X-Content-Type-Options': 'nosniff',
    },
  });
}
# Hang's workstream notes (Workstream C + foundation slice)

Branch: `hang`. Covers `hang.md` Hour 0 + Workstream C tasks 1–10.
Verified: `npm run typecheck` ✓, `npm run lint` (0 errors) ✓, `npm test` (263 pass) ✓, `npm run build` ✓ (with dummy env).

## §17 resolutions (items 1, 2, 3, 10, 15)

- **Item 1 — @google/genai API: RESOLVED by package inspection** (`@google/genai@3.0.0` types).
  `ai.models.generateContent({ model, contents, config })` with `config.tools = [{ googleSearch: {} }]`;
  grounding read from `candidates[0].groundingMetadata` (`groundingChunks[].web`, `webSearchQueries`,
  `searchEntryPoint.renderedContent`). JSON mode via `responseMimeType: 'application/json'` + `responseSchema`,
  images as `{ inlineData: { mimeType, data } }` parts. Implemented in `src/lib/gemini/client.ts`.
  Live proof still needs a key: `GEMINI_API_KEY=... node scripts/gemini-smoke.mjs`.
- **Item 2 — Grounding terms: NOT resolved, needs a human.** I could not read the Gemini API Additional
  Terms from here. Implementation follows the SPEC's cautious default: 24 h discovery-URL cache
  (`recipe_search_cache`), `searchEntryPoint.renderedContent` rendered unmodified in a sandboxed
  `<iframe srcdoc sandbox="allow-popups allow-popups-to-escape-sandbox">`. Human: read the terms,
  then keep/shorten/drop the cache.
- **Item 3 — 3.8-flash vs flash-lite: NOT resolved, needs a key.** `GEMINI_SEARCH_MODEL` is
  configurable (`src/lib/env.ts`, default `gemini-3.8-flash`). Human: time 3 discovery runs per model.
- **Item 10 — full step text: team decision needed; default (a) implemented.** Cook/detail views show
  full `HowToStep` text with attribution + always-visible "View original" link. No headnotes/stories
  are ever copied. Human: confirm (a) vs summary-plus-link (b).
- **Item 15 — dev/deploy flags: PARTIALLY resolved.**
  - `next dev --experimental-https` EXISTS in Next 16.4.5 (verified via `next dev --help`), with
    `--experimental-https-key/cert/ca` options. Use it for phone-on-LAN testing.
  - Dockerfile standalone paths match the standard Next 16 output (`.next/standalone/server.js` +
    `.next/static` + `public/`); `npm run build` produces them (verified).
  - sslip.io fallback: unverified here; Caddy auto-TLS against it needs a VPS test.

## Deliberate deviations from SPEC (all marked "tune freely" or forced by tooling)

1. **expiryScore normalization** (`src/server/recipes/score.ts`): SPEC sketches cross-set normalization,
   which forbids streaming each candidate with its final score (F6 step 8). Using per-candidate
   saturating `Σw/(Σw+1)` instead. Ordering intent preserved; F6 AC6 test matches this formula.
2. **TypeScript 6.0.3, not 7.x**: typescript-eslint does not support TS 7, which broke `npm run lint`
   entirely. Pinned `typescript: 6.0.3` (exact). Revisit if Next/Auth0 require TS 7 features.
3. **ESLint flat config**: `FlatCompat` + `next/core-web-vitals` crashes under ESLint 10. Using the
